def close_duplicate_open_attempts(apps, schema_editor):
    """Before the constraint: keep each student's newest open attempt per quiz.

    Older duplicates (from double-taps before starts were serialised) are removed when
    empty, otherwise handed to the teacher as submitted work.
    """
    Attempt = apps.get_model("assessments", "Attempt")
    seen = set()
    for attempt in Attempt.objects.filter(status="in_progress").order_by("user_id", "quiz_id", "-started_at", "-id"):
        key = (attempt.user_id, attempt.quiz_id)
        if key not in seen:
            seen.add(key)
            continue
        if not attempt.answers.exists():
            attempt.delete()
        else:
            attempt.status = "needs_marking"
            attempt.submitted_at = attempt.deadline or attempt.started_at
            attempt.save(update_fields=["status", "submitted_at"])


